/* Encender D7 (RB14 a 0) */
PORTB &= ~0x4000;

/* Apagar D7 (RB14 a 1) */
PORTB |= 0x4000;

/* Invertir D9 (RB12) */
PORTB ^= 0x1000;

/* Encender D6 y apagar D9 */
PORTB &= ~0x8000;
asm("nop");
PORTB |= 0x1000;

/* Mostrar n (0 a 15) en los cuatro LED: activos a nivel bajo, se escribe ~n */
PORTB &= ~0xF000;                  // 1) bits 15-12 a 0
asm("nop");
PORTB |= (~n & 0x000F) << 12;      // 2) escribir ~n

/* Leer el pulsador SW2 (RB2): pulsado = 0 */
if ((PORTB & 0x0004) == 0) {
    /* SW2 pulsado */
}
